/* Font constants */
#define FONT_GLYPH_WIDTH 16
#define FONT_GLYPH_HEIGHT 8
#define FONT_TILES_PER_GLYPH 2
#define FONT_GLYPH_COUNT 91
#define FONT_TILES_COUNT 182
#define FONT_TILES_SIZE 2912
#define FONT_PALETTE_SIZE 4
#define FONT_CHARS_START 32
#define FONT_CHARS_END 122
#define FONT_BYTES_PER_TILE 16
#define FONT_BYTES_PER_GLYPH 32
#define FONT_BPP 2

/* Helper functions */
/* Get tile index from ASCII code: tile_index = (ascii_code - FONT_CHARS_START) * 2 */
static inline unsigned char get_char_tile(unsigned char ascii_code) {
    if (ascii_code < 32 || ascii_code > 122) return 0xFF;
    return (ascii_code - 32) * 2;
}

static inline int is_printable_char(unsigned char ascii_code) {
    return (ascii_code >= 32 && ascii_code <= 122);
}

/* Font tile data access macro */
/* Returns pointer to first tile of glyph (32 bytes = 2 tiles) */
#define FONT_GLYPH_DATA(tile_index) (&font_tiles[(tile_index) * 16])
